    reg [2:0] cnt2;
    reg [2:0] state;
    reg [2:0] next_state;
    reg in_reg;
    always @(posedge clk) begin
        in_reg <= in;
        case (state)
            3'd0: begin
                if (in_reg) begin
                    cnt <= 3'd1;
                    next_state <= 3'd1;
                end else begin
                    cnt <= 3'd0;
                    next_state <= 3'd0;
                end
