            3'd1: begin
                if (in_reg) begin
                    cnt <= cnt + 3'd1;
                    next_state <= 3'd1;
                end else begin
                    cnt <= 3'd0;
                    next_state <= 3'd2;
                end
            end
            3'd2: begin
                if (in_reg) begin
                    cnt <= cnt + 3'd1;
                    next_state <= 3'd3;
                end else begin
                    cnt <= 3'd0;
                    next_state <= 3'd0;
                end
            end
            3'd3: begin
