// Synchronous HDLC framing, with explicit discard, flag, and error signals.
// The FSM is a Moore-type (combinational next-state function) finite
// state machine, with the state explicitly named "state" and the next
// state explicitly named "nextstate".
module TopModule(
    input  clk,
    input  reset,
    input  in,
    output reg disc,
    output reg flag,
    output reg err
);
    reg [2:0] cnt;
    reg [2:0] state, nextstate;
    always @(*) begin
        case (state)
            3'd0: nextstate = in ? 3'd1 : 3'd0;
            3'd1: nextstate = in ? 3'd2 : 3'd0;
            3'd2: nextstate = in ? 3'd3 : 3'd0;
            3'd3: nextstate = in ? 3'd4 : 3'd0;
            3'd4: nextstate = in ? 3'd5 : 3'd0;
            3'd5: nextstate = in ? 3'd6 : 3'd1;
            3'd6: nextstate = in ? 3'd0 : 3'd1;
            default: nextstate = 3'd0;
        endcase
    end
    always @(posedge clk) begin
        if (reset) begin
            state <= 3'd0;
            cnt <= 3'd0;
            disc <= 1'b0;
            flag <= 1'b0;
            err <= 1'b0;
        end else begin
            state <= nextstate;
            cnt <= (state == 3'd6) ? cnt + 3'd1 : (state != 3'd0) ? 3'd1 : 3'd0;
            disc <= (state == 3'd6) & in;
            flag <= (state == 3'd6) & ~in;
            err <= (state > 3'd6);
        end
    end
endmodule

