// Synchronous HDLC framing: recognize three sequences (flag, disc, err) and
// discard the bit indicated by the flag. The FSM is a Moore type: it has an
// output function that depends only on its current state and the input (no
// combinational logic in the transition function).
module TopModule(
    input  clk,
    input  reset,
    input  in,
    output reg disc,
    output reg flag,
    output reg err
);
    reg [2:0] cnt;
    reg [2:0] state;
    parameter [2:0] IDLE = 3'b000, FLAG1 = 3'b001, FLAG2 = 3'b010, ERR = 3'b011, DISC = 3'b100;
    always @(posedge clk) begin
        if (reset) begin
            state <= IDLE;
            cnt <= 3'b0;
            disc <= 1'b0;
            flag <= 1'b0;
            err <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    if (in) begin
                        state <= FLAG1;
                        cnt <= 3'b0;
                    end else begin
                        state <= IDLE;
                        cnt <= cnt + 1'b1;
                    end
                end
                FLAG1: begin
                    if (in) begin
                        state <= FLAG2;
                        cnt <= 3'b0;
                    end else begin
                        state <= ERR;
                        cnt <= 3'b0;
                    end
                end
                FLAG2: begin
                    if (in) begin
                        state <= DISC;
                        cnt <= 3'b0;
                        disc <= 1'b1;
                    end else begin
                        state <= FLAG1;
                        cnt <= cnt + 1'b1;
                    end
                end
                ERR: begin
                    if (in) begin
                        state <= ERR;
                        cnt <= cnt + 1'b1;
                    end else begin
                        state <= IDLE;
                        cnt <= 3'b0;
                        err <= 1'b1;
                    end
                end
                DISC: begin
                    if (in) begin
                        state <= FLAG1;
                        cnt <= 3'b0;
                        disc <= 1'b0;
                    end else begin
                        state <= ERR;
                        cnt <= 3'b0;
                    end
                end
            endcase
            flag <= (state == FLAG2);
        end
    end
endmodule

