// Synchronous HDLC framing: detect and discard the bit signaled by a 0111110
// sequence, signal the start/end of a frame by a 01111110, and signal an
// error if 7 or more 1s are seen (01111111...). The FSM is a Moore type,
// i.e., it outputs a function of the current state and the input, and goes to
// the next state immediately.
module TopModule(
    input  clk,
    input  reset,
    input  in,
    output reg disc,
    output reg flag,
    output reg err
);
    reg [2:0] state;
    reg [2:0] next_state;
    always @(*) begin
        case (state)
            3'd0: next_state = in ? 3'd1 : 3'd0;
            3'd1: next_state = in ? 3'd2 : 3'd0;
            3'd2: next_state = in ? 3'd3 : 3'd0;
            3'd3: next_state = in ? 3'd4 : 3'd0;
            3'd4: next_state = in ? 3'd5 : 3'd0;
            3'd5: next_state = in ? 3'd6 : 3'd1;
            3'd6: next_state = in ? 3'd3 : (in ? 3'd0 : 3'd7);
            3'd7: next_state = in ? 3'd3 : 3'd0;
            default: next_state = 3'd0;
        endcase
    end
    always @(posedge clk) begin
        if (reset) begin
            state <= 3'd0;
            disc <= 1'b0;
            flag <= 1'b0;
            err <= 1'b0;
        end else begin
            state <= next_state;
            disc <= (state == 3'd6) & ~in;
            flag <= state == 3'd6;
            err <= state == 3'd7;
        end
    end
endmodule

